import json

# Let me check the JSON file for the table structure
with open('/app/resources/treasury_bulletin_1970_12.json', 'r') as f:
    data = json.load(f)

# Find the PDO-2 table in the JSON
def find_table(obj, target=None):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target and target in str(k).upper():
                return k, v
            yield from find_table(v, target)
    elif isinstance(obj, list):
        for item in obj:
            yield from find_table(item, target)

# Find tables with "bills" in them
for k, v in find_table(data, "PDO"):
    print(f"Key: {k}, Type: {type(v)}")
    if isinstance(v, list) and len(v) > 0:
        print(f"  First few elements: {v[:3]}")
        break

# Actually, let me just look at the raw structure
print("\nSearching for 'Offerings' table...")
for k, v in data.items():
    if 'offering' in str(k).lower():
        print(f"Found: {k}")
